var PAGE='Proto iOS '+APP.split('/')[0];
function txt(p,t,size,role,w){return H.text({parent:p,text:t,size:size||14,weight:size>=20?7:5,color:H.sw(APP,role||'ink'),w:w||326})}
function col(p,n,w,pad,gap,fill){var f=H.frame({parent:p,name:n,dir:'col',w:w||358,pad:pad||0,gap:gap===undefined?12:gap,fill:fill?H.sw(APP,fill):null,radius:16});f.stackLayout.alignItems=sketch.StackLayout.AlignItems.Start;return f}
function btn(p,t,id,kind,w){var f=H.frame({parent:p,name:'link:'+id,w:w||326,h:48,pad:12,radius:12,fill:H.sw(APP,kind==='primary'?'accent':kind==='danger'?'danger':'surface'),border:kind?'':H.sw(APP,'line'),justify:sketch.StackLayout.JustifyContent.Center});H.text({parent:f,text:t,size:15,weight:6,color:kind?'#ffffff':H.sw(APP,'ink')});H.order(f);return f}
function row(p,t,sub,id,status){var f=col(p,'link:'+id,358,16,8,'surface');f.style.borders=[{color:H.sw(APP,'line'),thickness:1,position:sketch.Style.BorderPosition.Inside}];if(status)txt(f,status,11,'accent',326);txt(f,t,16,'ink',326);if(sub)txt(f,sub,12,'secondary',326);H.order(f);return f}
function gapfill(p){var f=col(p,'flex-space',358,0,0);f.verticalSizing=sketch.FlexSizing.Fill;return f}
function composer(p){var wrap=col(p,'composer-dock',358,0,0);var i=H.inst('Composer/'+APP+'/phone-docked',wrap);i.frame.width=358;i.overrides.filter(function(o){return o.property==='stringValue'&&String(o.value).indexOf('Message Harso')>=0}).forEach(function(o){o.value='Message Weave…'});H.link(i,'conversation');H.order(wrap);return wrap}
function findScreen(){return H.page(PAGE).layers.find(function(l){return l.name==='Screen/ios/'+APP+'/'+ID})}
function close(s,b){H.order(b);H.relayout(s);s.frame.width=390;s.frame.height=844;s.frame.x=IDS.indexOf(ID)*510;s.frame.y=0;H.out({id:ID,app:APP,frame:s.id,w:s.frame.width,h:s.frame.height});}
function thread(b){txt(b,'PERSONAL',11,'tertiary');txt(b,'Move the billing webhook handler onto the new ledger client',22);var u=col(b,'user-message',358,16,0,'hover');txt(u,'Run only the webhook tests first.',14);H.order(u);var a=col(b,'assistant-message',358,0,10);H.icon({parent:a,d:H.paths.sparkles,size:22,color:H.hex(APP,'accent')});txt(a,"Running only services/billing/webhook.test.ts. I’ll ask before executing anything.",14);H.order(a);row(b,'terminal','Awaiting permission to run the test command.','conversation--approval','APPROVAL REQUIRED');row(b,'Prepare the release','Release checks · Verify the candidate · 1 / 3','activity--work','● RUNNING');gapfill(b);composer(b)}

var s=findScreen(),b=s.layers.find(function(l){return l.name==='body'});
if(ID==='signin'){var top=col(b,'welcome',358,16,16);var sp=H.frame({parent:top,name:'breathing-room',w:1,h:72});H.icon({parent:top,d:H.paths.sparkles,size:44,color:H.hex(APP,'accent')});txt(top,'Sign in to Weave',28);txt(top,'Continue with Apple, Google, or email.',14,'secondary');H.order(top);var form=col(b,'signin-form',358,16,16);['apple','google'].forEach(function(provider){var w=col(form,'link:home',326,0,0);w.stackLayout.alignItems=sketch.StackLayout.AlignItems.Center;var i=H.inst('SocialButton/'+APP+'/'+provider+'/default',w);i.frame.width=326;i.frame.height=48;H.order(w)});txt(form,'or continue with email',12,'tertiary');txt(form,'Email',13);var field=col(form,'email-field',326,14,0,'surface');txt(field,'you@example.com',15,'tertiary',298);H.order(field);btn(form,'Continue','home','primary');txt(form,'We’ll email you a secure sign-in link.',12,'secondary');H.order(form)}
if(ID==='home'){txt(b,'Good morning',13,'secondary');txt(b,'What can I help with?',28);var chips=H.frame({parent:b,name:'project-chips',dir:'row',gap:8,w:358});btn(chips,'Personal','project',null,172);btn(chips,'All projects','projects',null,178);H.order(chips);txt(b,'Recent conversations',16);row(b,'Move the billing webhook handler…','Personal · Just now','conversation');row(b,'Prepare the release','Personal · Today','conversation');gapfill(b);composer(b)}
if(ID.indexOf('conversation')===0)thread(b);
if(ID==='search'){var r=H.frame({parent:b,name:'search-toolbar',dir:'row',gap:8,w:358});var f=H.inst('SearchField/'+APP+'/typing',r);f.frame.width=270;f.overrides.filter(function(o){return o.property==='stringValue'}).forEach(function(o){o.value='billing'});H.link(f,'search');btn(r,'Cancel','back',null,80);H.order(r);txt(b,'CONVERSATIONS',11,'tertiary');row(b,'Move the billing webhook handler…','Personal · Updated just now','conversation');row(b,'Billing release checks','Personal · Yesterday','conversation');txt(b,'PROJECTS',11,'tertiary');row(b,'Personal','2 matching conversations','project');txt(b,'Search across your conversations and projects.',12,'secondary')}
if(ID==='activity'){txt(b,'Your work, in motion',26);txt(b,'Review progress and respond when needed.',14,'secondary');row(b,'Prepare the release','Release checks · Verify the candidate\n1 / 3 · Workspace sprite','activity--work','● RUNNING');row(b,'Billing webhook tests','Permission needed to run a command','activity--work','NEEDS YOUR INPUT');txt(b,'You’re up to date',13,'tertiary')}
if(ID==='activity--work'){txt(b,'Prepare the release',26);txt(b,'Release checks · Workspace sprite',13,'secondary');var objective=col(b,'objective',358,16,8,'surface');txt(objective,'OBJECTIVE',11,'tertiary');txt(objective,'Verify the candidate before preparing the release.',16);txt(objective,'Attempt 1 · Running',12,'accent');H.order(objective);txt(b,'Plan',18);row(b,'1  Verify the candidate','Waiting for your approval','conversation--approval','IN PROGRESS');row(b,'2  Run release checks','Starts after verification','activity--work','QUEUED');row(b,'3  Prepare the release','Summarize results and next steps','activity--work','QUEUED');var actions=H.frame({parent:b,name:'work-actions',dir:'row',gap:8,w:358});btn(actions,'Steer','conversation',null,175);btn(actions,'Cancel','back',null,175);H.order(actions);btn(b,'Respond','conversation--approval','primary',358)}
